private Mappings getMissingMappings(Mappings currMappings, Mappings inputMappings) {
    Mappings missingMappings = new Mappings();

    // Iterate over the input mappings and add any mappings that are not
    // present in the current mappings to the missing mappings
    for (Map.Entry<String, Mapping> entry : inputMappings.entrySet()) {
        String fieldName = entry.getKey();
        Mapping mapping = entry.getValue();

        if (!currMappings.containsKey(fieldName)) {
            // No mapping for the field name, add it to the missing mappings
            missingMappings.put(fieldName, mapping);
        }
    }

    return missingMappings;
}
