    int lastRow = table.rowAtPoint(new Point(visibleRect.getWidth(), visibleRect.getHeight()));

    // If the selected row is offscreen, scroll the table to make it visible
    if (row < firstRow || row > lastRow) {
        // Calculate the new scroll position
        JViewport viewport = pane.getViewport();
        int currentScroll = viewport.getViewPosition().y;
        int nextScroll = currentScroll + (row - firstRow) * table.getRowHeight();

        // Set the new scroll position and repaint the table
        viewport.setViewPosition(new Point(0, nextScroll));
        table.repaint();
    }
}

